# ================================================================ OA 15 · cartas, instrucciones, afiches, reportes
reg(
    OA15, 1,
    "Este cuaderno, lápiz y las situaciones escritas en los ejercicios. Sin materiales especiales.",
    "Aprenderé a elegir el formato de escritura (carta, instrucciones, afiche o reporte) según lo que quiero lograr y a quién le escribo. Sirve para que mi mensaje llegue bien.",
    ["Sé escribir oraciones completas.", "Sé que hay textos de distintos tipos."],
    ["Cada vez que escribes, tienes un propósito: lo que quieres lograr. Puedes querer hablarle a una persona, enseñar cómo se hace algo, avisar a muchas personas o contar lo que hiciste. Según el propósito y el destinatario (a quién le escribes) conviene un formato distinto.",
     "La carta sirve para comunicarte con una persona. Las instrucciones sirven para enseñar los pasos de algo. El afiche sirve para avisar o invitar a muchas personas, con letras grandes y pocos datos. El reporte sirve para contar lo que hiciste y lo que observaste en una experiencia.",
     "Si usas el formato equivocado, el mensaje se pierde. Un afiche con un párrafo largo no se lee desde lejos. Unas instrucciones sin pasos ordenados no se pueden seguir. Antes de escribir, pregúntate: ¿para qué escribo y quién lo leerá?"],
    [("propósito", "lo que quieres lograr con un texto"), ("destinatario", "persona o grupo a quien se escribe"), ("formato", "forma y partes que tiene un tipo de texto"), ("mensaje", "lo que quieres comunicar")],
    [("Elegir el formato", "Quieres invitar a todo el colegio a una feria del libro. ¿Escribes una carta a una persona o un afiche?", ["Son muchas personas.", "El afiche avisa a muchos con pocas palabras.", "Elijo el afiche."], "Un afiche"),
     ("Elegir según el propósito", "Quieres enseñar a un amigo cómo armar un barco de papel. ¿Una carta de saludo o unas instrucciones?", ["Quiero que siga pasos.", "Las instrucciones tienen pasos ordenados.", "Elijo instrucciones."], "Unas instrucciones")],
    [("Usar siempre el mismo formato.", "Cada propósito pide uno distinto.", "Pregunta: ¿para qué y para quién escribo?"), ("Escribir un afiche con mucho texto.", "No se lee de lejos.", "Usa letras grandes y pocos datos.")],
    ([E("¿Qué formato sirve para comunicarte con una sola persona: una carta o un afiche?", "Una carta", "La carta tiene destinatario."),
      E("¿Qué formato enseña pasos para hacer algo: instrucciones o reporte?", "Instrucciones", "Muestran el orden de los pasos."),
      E("¿Qué formato avisa a muchas personas con letras grandes: carta o afiche?", "Afiche", "Se lee de lejos.")],
     [E("En Lenguaje: ¿Qué es el propósito de un texto?", "Lo que quiero lograr al escribirlo", "Define qué formato conviene."),
      E("¿Qué formato cuenta lo que hiciste y observaste en una experiencia?", "Reporte", "Informa lo realizado y lo visto."),
      E("¿Por qué un afiche no debe tener un párrafo largo?", "Porque no se puede leer de lejos", "Debe ser breve y claro.")],
     [E("Quieres contarle a un amigo que vive lejos cómo te fue en el colegio. ¿Qué formato usas?", "Carta", "Es un mensaje para una persona."),
      E("Quieres avisar que el curso hará una venta de pasteles. ¿Qué formato usas?", "Afiche", "Informa a muchas personas."),
      E("Quieres contar lo que viste al regar una planta durante una semana. ¿Qué formato usas?", "Reporte", "Cuenta lo observado.")],
     [E("Tomás escribió un párrafo muy largo para anunciar un festival en el patio y lo pegó en la pared. ¿Qué formato debió usar y cómo?", "Un afiche, con letras grandes y pocos datos", "El anuncio debe leerse rápido."),
      E("Una niña quiere que su hermano arme una torre de cubos siguiendo su guía. Ella le escribe una carta de saludo. ¿Qué falló?", "Debió escribir instrucciones con pasos", "La carta no muestra los pasos.")],
     [E("Elige el formato para cada situación: a) enseñar a lavarse las manos, b) agradecer un regalo a una persona, c) invitar al curso a una feria. Formatos: afiche, carta, instrucciones.", "a) instrucciones, b) carta, c) afiche", "Cada propósito pide su formato."),
      E("Quieres contar a tu curso qué pasó con una semilla que regaste cinco días. ¿Qué formato usas y por qué?", "Un reporte, porque cuenta lo hecho y observado", "El reporte informa de una experiencia.")]),
    [E("Quieres pedirle a tu vecino que no deje su perro suelto. ¿Qué formato usas: una carta corta o un reporte?", "Una carta corta", "Es un mensaje a una persona.")],
    [E("¿Cada formato tiene un propósito distinto?", "Sí", "Por eso se elige según lo que quiero lograr."),
     E("¿El afiche es largo y detallado?", "No", "Es breve y se lee de lejos."),
     E("¿Las instrucciones enseñan pasos?", "Sí", "Muestran qué hacer en orden.")],
    ("Para cada situación escribe qué formato usarías (carta, instrucciones, afiche o reporte) y una frase que diga por qué: 1) Quieres avisar al colegio de una campaña de abrigo. 2) Quieres explicar cómo plantar un poroto. 3) Quieres contarle a una amiga lejana que te cambiaste de pieza. 4) Quieres contar qué ocurrió cuando guardaste un hielo al sol.", "1) Afiche, porque avisa a muchos. 2) Instrucciones, porque enseña pasos...", ["elige un formato para cada una de las cuatro situaciones", "da una razón por cada formato", "las razones nombran el propósito o el destinatario"], ["cuatro formatos con razón"], ["elegir el mismo para todas", "no justificar"], "Lee tus elecciones a otra persona y pregunta si está de acuerdo."),
    "Escribe una situación en que una carta sea mejor que un afiche.",
    "Inventa una situación para cada uno de los cuatro formatos.")

reg(
    OA15, 2,
    "Este cuaderno, lápiz y la carta escrita en los ejercicios. Sin materiales especiales.",
    "Aprenderé las partes de una carta y a escribir un mensaje claro. Sirve para comunicarme con una persona y que me entienda.",
    ["Sé elegir el formato según el propósito.", "Sé escribir oraciones completas."],
    ["Una carta tiene partes que siempre van en el mismo orden. Al comienzo va el lugar y la fecha. Después va el saludo, que nombra al destinatario («Querida abuela:»). Luego va el mensaje, que es lo que quieres contar o pedir. Al final van la despedida («Un abrazo») y la firma, que es tu nombre.",
     "Un mensaje claro dice lo principal con orden. Primero cuenta la noticia o el motivo de la carta. Luego agrega uno o dos detalles. Si haces una pregunta o un pedido, escríbelo de forma que se entienda lo que esperas. Evita mezclar muchos temas.",
     "Escribe con tono respetuoso y adecuado a quien recibe la carta. A una abuela puedes escribirle con cariño; a la directora, con respeto y formalidad. No incluyas datos personales delicados, como la dirección exacta de tu casa o claves, en una carta que podría perderse."],
    [("saludo", "palabras con que comienza una carta y que nombran al destinatario"), ("despedida", "palabras con que termina una carta"), ("firma", "nombre de quien escribe la carta"), ("pedido", "algo que se solicita en una carta")],
    [("Reconocer las partes", CARTA + " ¿Cuál es el saludo?", ["El saludo nombra a quien recibe la carta.", "Está después del lugar y la fecha.", "Dice «Querida abuela»."], "Querida abuela"),
     ("Ordenar las partes", "Desordenadas: despedida, saludo, lugar y fecha, mensaje, firma. ¿En qué orden van?", ["Primero el lugar y la fecha.", "Luego el saludo y el mensaje.", "Al final la despedida y la firma."], "Lugar y fecha, saludo, mensaje, despedida, firma")],
    [("Olvidar el saludo o la despedida.", "La carta queda sin comienzo o sin cierre.", "Revisa que tenga todas las partes."), ("Mezclar muchos temas en el mensaje.", "El destinatario no entiende lo principal.", "Cuenta lo principal y uno o dos detalles.")],
    ([E(CARTA + " ¿Quién escribe la carta?", "Lola", "Es el nombre de la firma."),
      E(CARTA + " ¿Cuál es la despedida?", "Un abrazo grande", "Cierra el mensaje antes de la firma."),
      E(CARTA + " ¿A quién se dirige la carta?", "A la abuela", "El saludo nombra a la destinataria.")],
     [E("¿Qué parte de la carta va primero: el saludo o el lugar y la fecha?", "El lugar y la fecha", "Están al comienzo."),
      E("¿Qué es la firma de una carta?", "El nombre de quien la escribe", "Va al final."),
      E(CARTA + " ¿Qué pregunta hace Lola en el mensaje?", "Si la abuela vendrá pronto a verla", "Es el pedido de la carta.")],
     [E("Escribes a tu profesora. ¿Qué saludo conviene: A) «Estimada profesora:», B) «Oye, profe:», C) «Chao:»?", "A", "A nombra a la destinataria con respeto; B es muy informal y C es una despedida."),
      E("Completa con la despedida: «Te mando un ___ grande, tu amigo Pedro». ¿Qué palabra falta: abrazo o lápiz?", "Abrazo", "Es una despedida cariñosa."),
      E(CARTA + " ¿Cuántas veces dice Lola que se cayó?", "2", "Dice que se cayó dos veces.")],
     [E("Una carta empieza: «Querida abuela: me va bien». No tiene lugar ni fecha. ¿Qué parte falta al comienzo?", "El lugar y la fecha", "Van antes del saludo."),
      E("Ema le escribe a la directora: «Hola, tía, dame permiso». ¿Qué falla en el tono?", "Es poco respetuoso para la directora", "La carta debe ser formal.")],
     [E("Ordena las cinco partes: firma, mensaje, despedida, saludo, lugar y fecha. Escribe el orden correcto.", "Lugar y fecha, saludo, mensaje, despedida, firma", "Es el orden de una carta."),
      E("Escribes a la directora. ¿Qué despedida es respetuosa: A) «Atentamente», B) «Chao, chao», C) «Besitos»?", "A", "Atentamente es formal; B y C son demasiado informales para la directora.")]),
    [E("Quieres pedirle a la directora que el curso use el patio el viernes. ¿Qué saludo escribes: «Estimada directora:» o «Hola, amiga:»?", "Estimada directora:", "Es respetuoso y formal.")],
    [E("¿La carta lleva saludo?", "Sí", "Nombra al destinatario."),
     E("¿La firma va al comienzo?", "No", "Va al final."),
     E("¿El mensaje debe ser claro?", "Sí", "Para que el destinatario entienda.")],
    ("Escribe una carta corta a una persona que vive lejos o a tu profesora. Debe tener: lugar y fecha, saludo, un mensaje de dos o tres oraciones con una noticia y una pregunta, despedida y firma.", "Santiago, 3 de junio. Querido tío: ... Un abrazo, Ema.", ["incluye las cinco partes", "el mensaje cuenta una noticia", "hace una pregunta", "el tono es adecuado"], ["carta escrita"], ["olvidar alguna parte", "mezclar muchos temas"], "Léela a otra persona y pregúntale si entendió qué quieres contar."),
    "Escribe un saludo y una despedida para una carta a tu mejor amigo.",
    "Escribe una carta de tres líneas pidiendo permiso a la directora para usar el patio.")

reg(
    OA15, 3,
    "Este cuaderno, lápiz y las instrucciones escritas en los ejercicios. Sin materiales especiales.",
    "Aprenderé a escribir instrucciones que otra persona pueda seguir y comprobar. Sirve para enseñar cómo se hace algo en pasos claros.",
    ["Sé elegir el formato según el propósito.", "Sé ordenar acciones en secuencia."],
    ["Unas instrucciones enseñan cómo hacer algo. Llevan un título que dice qué se va a hacer, una lista de materiales y los pasos numerados. Cada paso empieza con un verbo que da una orden, como «pon», «moja» o «coloca», y dice una sola acción.",
     "Las instrucciones deben ser comprobables: otra persona puede seguirlas y conseguir el mismo resultado. Por eso los pasos van en orden, no faltan materiales y las medidas son claras. «Agrega un poco de agua» es mejor que «agrega lo necesario».",
     "Para comprobar, pide a alguien que haga cada paso tal como lo escribiste. Si se confunde, el paso necesita más claridad. Piensa también en la seguridad: no incluyas pasos que usen fuego, objetos cortantes o vidrio sin una persona adulta."],
    [("instrucciones", "texto que enseña cómo hacer algo paso a paso"), ("materiales", "cosas necesarias para hacer algo"), ("paso", "una acción dentro de las instrucciones"), ("comprobable", "que se puede probar siguiendo los pasos")],
    [("Leer unas instrucciones", INSTR + " ¿Cuál es el primer paso?", ["Los pasos están numerados.", "El paso 1 es el primero.", "Pon algodón dentro del vaso."], "Poner algodón dentro del vaso"),
     ("Arreglar un paso", "Un paso dice: «Agrega lo necesario». ¿Cómo lo mejoras?", ["«Lo necesario» no dice cuánto.", "Una persona no sabrá qué hacer.", "Escribo: Agrega un poco de agua."], "Agrega un poco de agua")],
    [("Escribir varios pasos en una sola oración.", "Es difícil seguirlos.", "Un paso, una acción."), ("Olvidar un material o un paso.", "Quien sigue las instrucciones se queda trabado.", "Prueba las instrucciones con otra persona.")],
    ([E(INSTR + " ¿Cuántos pasos tiene?", "5", "Están numerados del 1 al 5."),
      E(INSTR + " ¿Con qué verbo empieza el paso 3?", "Coloca", "Dice «Coloca el poroto sobre el algodón»."),
      E(INSTR + " ¿Cuáles son los materiales: vaso, algodón, poroto y agua, o solo un vaso?", "Vaso, algodón, poroto y agua", "Están en la lista de materiales.")],
     [E("¿Cada paso de unas instrucciones tiene una acción o varias?", "Una", "Así se puede seguir."),
      E("¿Qué quiere decir que unas instrucciones sean comprobables?", "Que otra persona puede seguirlas y lograr el mismo resultado", "Se prueban haciendo los pasos."),
      E(INSTR + " ¿Cuándo se agrega agua según el paso 5?", "Cada dos días", "Lo dice el último paso.")],
     [E("Ordena los pasos de lavarse las manos: 1) Seca tus manos. 2) Enjabónalas. 3) Moja tus manos. 4) Enjuágalas. Escribe el orden.", "3, 2, 4, 1", "Mojar, enjabonar, enjuagar y secar."),
      E("¿Cuál paso es más claro: A) «Pon el agua», B) «Pon un poco de agua en el vaso»?", "B", "B dice cuánto y dónde; A no lo dice."),
      E(INSTR + " ¿Cuántos días pasan entre dos riegos?", "2", "El paso 5 dice cada dos días.")],
     [E("Una niña escribió: «Moja el algodón, pon el poroto y deja el vaso en la ventana». ¿Qué problema tiene?", "Tres acciones en un solo paso", "Cada paso debe tener una acción."),
      E("Quien siguió unas instrucciones se quedó trabado porque no había materiales en la lista. ¿Qué falló?", "Faltó la lista de materiales completa", "Sin materiales no se puede hacer el paso.")],
     [E("Para armar un barco de papel, ¿cuál es un paso 1 claro: A) «Pon una hoja de papel sobre la mesa», B) «Haz el barco», C) «La hoja»?", "A", "A empieza con verbo y dice una sola acción clara; B es demasiado general y C no es una acción."),
      E(INSTR + " Un niño pone el poroto antes de poner el algodón. ¿Qué paso no siguió en orden: el 1 o el 5?", "El 1", "El algodón va primero.")]),
    [E("Quieres enseñar a regar una planta. Escribes: «1. Llena un vaso con agua. 2. Echa un poco de agua a la tierra». ¿Los pasos tienen un verbo al comienzo?", "Sí", "Llena y echa son verbos.")],
    [E("¿Los pasos deben ir en orden?", "Sí", "Si no, no se pueden seguir."),
     E("¿Debo incluir fuego en unas instrucciones para niños sin adulto?", "No", "No es seguro."),
     E("¿Cada paso empieza con un verbo?", "Sí", "Dice qué hacer.")],
    ("Escribe unas instrucciones para lavarse los dientes o para armar un barco de papel. Debe tener: un título, una lista de materiales, cinco pasos numerados que empiecen con verbo y una persona de tu casa debe poder seguirlos.", "Cómo lavarse los dientes. Materiales: cepillo, pasta y agua. 1. Moja el cepillo...", ["tiene título y materiales", "tiene cinco pasos numerados", "cada paso empieza con verbo y tiene una acción", "el orden es lógico"], ["instrucciones por escrito"], ["varias acciones en un paso", "olvidar un material"], "Pide a alguien que haga los pasos y anota dónde se confunde."),
    "Escribe tres pasos para guardar los útiles en la mochila.",
    "Reescribe un paso confuso de tus instrucciones para hacerlo más claro.")

reg(
    OA15, 4,
    "Este cuaderno, lápiz y los afiches descritos en los ejercicios. Sin materiales especiales.",
    "Aprenderé a hacer un afiche claro con un título grande, datos y un llamado. Sirve para avisar o invitar a muchas personas.",
    ["Sé elegir el formato según el propósito.", "Sé que un texto tiene una jerarquía de importancia."],
    ["Un afiche es un cartel que avisa algo a muchas personas. Debe leerse de lejos y rápido, por eso tiene pocas palabras. Lleva un título grande que dice de qué se trata, una imagen o dibujo, los datos importantes (qué, cuándo, dónde) y un llamado a la acción, que es lo que quieres que hagan.",
     "La jerarquía visual es el orden de importancia: lo más importante se escribe más grande y lo menos importante más chico. El título es lo más grande, luego los datos y por último el detalle. Así el ojo sabe qué leer primero.",
     "Por ejemplo, un afiche de una feria: título grande «Feria del libro», imagen de un libro, datos «Viernes 15, 10:00, sala de 3.º A» y llamado «¡Te esperamos!». Todo lo demás sobra. Usa colores que se vean bien juntos y deja espacios libres."],
    [("afiche", "cartel que avisa algo a muchas personas"), ("jerarquía visual", "orden de importancia mostrado con tamaños"), ("llamado a la acción", "frase que dice lo que quieres que las personas hagan"), ("título", "frase grande que dice de qué trata")],
    [("Identificar las partes", "Afiche: «FERIA DEL LIBRO» (grande). Dibujo de un libro. «Viernes 15, 10:00, sala de 3.º A». «¡Te esperamos!» ¿Cuál es el llamado a la acción?", ["El llamado dice lo que quieren que hagan.", "Invita a asistir.", "Es «¡Te esperamos!»."], "¡Te esperamos!"),
     ("Aplicar la jerarquía", "En el afiche, ¿qué va más grande: el título o la hora?", ["El título es lo más importante.", "La hora es un dato.", "El título va más grande."], "El título")],
    [("Escribir un afiche con mucho texto.", "No se lee de lejos.", "Pocas palabras y letras grandes."), ("Olvidar un dato importante, como el lugar.", "Nadie sabrá dónde ir.", "Revisa qué, cuándo y dónde.")],
    ([E("En un afiche, ¿el título es lo más grande o lo más chico?", "Lo más grande", "Es lo primero que se lee."),
      E("¿Un afiche tiene pocas palabras o muchas?", "Pocas", "Debe leerse rápido."),
      E("«¡Te esperamos!» ¿es un llamado a la acción o un dato?", "Un llamado a la acción", "Invita a participar.")],
     [E("¿Qué es la jerarquía visual en un afiche?", "El orden de importancia mostrado con tamaños", "Lo más importante va más grande."),
      E("¿Qué tres datos suele tener un afiche: qué, cuándo y dónde, o color, tamaño y precio?", "Qué, cuándo y dónde", "Son los datos básicos."),
      E("¿Para qué sirve un dibujo en un afiche?", "Para llamar la atención y mostrar de qué trata", "Atrae la mirada.")],
     [E("Falta en el afiche: «FERIA DEL LIBRO. Viernes 15, 10:00. ¡Te esperamos!». ¿Qué dato falta: el lugar o el nombre del autor?", "El lugar", "No dice dónde será."),
      E("Quieres un afiche para una campaña de abrigo. ¿Cuál título conviene: «Dona abrigo» o «Una campaña que se realizará con el objetivo de recolectar prendas»?", "Dona abrigo", "Es breve y claro."),
      E("Ordena de más grande a más chico en un afiche: datos, título, detalle. Escribe el orden.", "Título, datos, detalle", "La jerarquía va de lo más importante a lo menos.")],
     [E("Marta puso la hora en letras enormes y el título chico. ¿Qué error cometió?", "Alteró la jerarquía: lo más importante debe ir más grande", "El título debe verse primero."),
      E("Un afiche tiene tres párrafos largos. ¿Qué debe hacer para mejorarlo?", "Reducir a pocas palabras con letras grandes", "Un afiche se lee de lejos.")],
     [E("Un afiche invita a una carrera del curso. ¿Cuál es un buen llamado a la acción: A) «¡Ven a correr con nosotros!», B) «La carrera es una actividad deportiva», C) «Hay árboles en el patio»?", "A", "A dice lo que quieres que hagan; B y C no invitan a nada."),
      E("Para un afiche sobre cuidar el agua, ¿qué título es mejor: A) «Cuida el agua», B) «Es importante que todas las personas piensen en el cuidado del agua»?", "A", "A es corto y se lee de lejos; B es demasiado largo.")]),
    [E("Necesitas avisar del paseo del curso el jueves 20 a las 9:00 en la entrada del colegio. ¿Qué datos pones: qué, cuándo y dónde, o solo el nombre del profesor?", "Qué, cuándo y dónde", "El lector necesita saber a qué ir.")],
    [E("¿El afiche usa letras grandes?", "Sí", "Debe leerse de lejos."),
     E("¿Un afiche necesita datos como cuándo y dónde?", "Sí", "Sin ellos no sirve."),
     E("¿Hay que escribir mucho texto?", "No", "Debe tener pocas palabras.")],
    ("Diseña un afiche para anunciar una de estas ideas: una campaña de cuidado del agua, una feria del libro o una carrera del curso. Dibuja o describe en tu cuaderno: un título grande, una imagen, los tres datos (qué, cuándo, dónde, inventados por ti) y un llamado a la acción.", "Título: CUIDA EL AGUA. Dibujo de una gota. Datos: semana del agua, lunes 10, patio. Llamado: ¡Participa!", ["tiene título grande", "tiene una imagen o dibujo", "incluye qué, cuándo y dónde", "tiene un llamado a la acción", "usa pocas palabras"], ["afiche dibujado o descrito"], ["escribir mucho texto", "olvidar el lugar o la fecha"], "Muéstralo desde lejos y pregunta si se lee el título."),
    "Escribe un título y un llamado para un afiche sobre reciclar papel.",
    "Rehace un afiche con la jerarquía invertida y explica qué cambió.")

